{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind k, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95ms, round(avg(duration)/1e6,1) avgms FROM abnormal_traces WHERE service_name = 'ts-route-service' AND span_name LIKE 'SELECT ts.route%' GROUP BY ALL ORDER BY 2",
          "claim": "In the incident window route-service's SELECT spans on ts.route_distances and ts.route_stations have p95 of about 420-630 ms, versus about 0.3 ms normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind k, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95ms, round(avg(duration)/1e6,1) avgms FROM normal_traces WHERE service_name = 'ts-route-service' AND span_name LIKE 'SELECT ts.route%' GROUP BY ALL ORDER BY 2",
          "claim": "Normal period: route-service's ts.route DB client spans run at about 0.2-0.3 ms average."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind k, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95ms, round(avg(duration)/1e6,1) avgms FROM abnormal_traces WHERE service_name = 'ts-route-service' AND attr_span_kind='Server' GROUP BY ALL ORDER BY 2",
          "claim": "route-service's own server endpoints slowed to multi-second p95 while its CPU and memory metrics stayed flat."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, round(avg(value),3) av, round(max(value),3) mx FROM abnormal_metrics WHERE service_name = 'mysql' AND metric IN ('k8s.pod.cpu.usage','container.cpu.usage') GROUP BY ALL",
          "claim": "mysql CPU stayed low, averaging about 0.005 during the incident, so the database server itself was not saturated."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-route-service' GROUP BY ALL",
          "claim": "route-plan-service's client calls into route-service averaged about 1850 ms during the incident, versus about 4.5 ms normally."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "travel-plan-service's calls to route-plan-service averaged about 1250 ms during the incident, versus about 49 ms normally."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, round(duration/1e6,1) ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' ORDER BY duration DESC LIMIT 5",
          "claim": "travel-plan-service's server spans for minStation, quickest and cheapest reached multi-second latencies in the incident window."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name caller, c.service_name callee, round(s.duration/1e6,1) ui_ms, round(c.duration/1e6,1) route_ms FROM abnormal_traces s JOIN abnormal_traces c ON c.parent_span_id=s.span_id WHERE s.service_name='ts-ui-dashboard' AND c.service_name='ts-route-service' AND s.span_name LIKE 'GET /api/v1/routeservice/routes%' ORDER BY s.duration DESC LIMIT 5",
          "claim": "ui-dashboard's GET routes requests took about 7.3 s, matching the route-service child span they wait on."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-basic-service' AND s.service_name='ts-route-service' GROUP BY ALL",
          "claim": "basic-service's calls to route-service rose to about 240 ms average, versus about 3 ms normally."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel2-service' AND s.service_name='ts-basic-service' GROUP BY ALL",
          "claim": "travel2-service's calls to basic-service rose to about 68 ms average, versus about 17 ms normally."
        }
      ]
    }
  ]
}
